import React from 'react';
import { TransactionForm } from './SharedForm';
import { TRANSACTION_TYPES } from './config';
import { Grid, TextField } from '@mui/material';

const BenefitFields = ({ form, set }) => (
  <>
    <Grid item xs={12} sm={6}>
      <TextField fullWidth size="small" label="مبلغ (ریال)" type="number" value={form.amount || ''}
        onChange={e => set('amount', e.target.value)} required />
    </Grid>
    <Grid item xs={12} sm={6}>
      <TextField fullWidth size="small" label="تعداد" type="number" value={form.quantity || ''}
        onChange={e => set('quantity', e.target.value)} helperText="در صورت نیاز (مثلاً تعداد بن کارت)" />
    </Grid>
    <Grid item xs={12} sm={6}>
      <TextField fullWidth size="small" label="شماره مرجع" value={form.reference_number || ''}
        onChange={e => set('reference_number', e.target.value)} />
    </Grid>
  </>
);

const BenefitForm = ({ onSuccess }) => {
  const cfg = TRANSACTION_TYPES.benefit;
  return (
    <TransactionForm
      title={`ثبت ${cfg.label}`}
      transactionType={cfg.key}
      subTypes={cfg.subTypes}
      color={cfg.color}
      onSuccess={onSuccess}
    >
      <BenefitFields />
    </TransactionForm>
  );
};

export default BenefitForm;
